import kotlinx.coroutines.*

fun main() = runBlocking {
    val job = launch { delay(100) }
    println("${job.isActive} ${job.isCompleted}")
    job.cancel()
    println("${job.isActive} ${job.isCancelled}")
    job.join()
    println("${job.isCancelled} ${job.isCompleted}")
}

