import kotlinx.coroutines.*

fun main() = runBlocking {
    try {
        coroutineScope {
            launch { delay(10); throw IllegalStateException("boom") }
            launch { delay(100); println("sibling done") }
        }
    } catch (e: IllegalStateException) {
        println("caught ${e.message}")
    }
    println("end")
}

